class Solution {
public:
    long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {
        int n = nums1.size(), m = nums2.size();
        const long long NEG = LLONG_MIN / 2;
        vector<vector<long long>> dp(n + 1, vector<long long>(m + 1, 0));
        for (int t = 1; t <= k; t++) {
            vector<vector<long long>> nd(n + 1, vector<long long>(m + 1, NEG));
            for (int i = 1; i <= n; i++)
                for (int j = 1; j <= m; j++) {
                    long long best = max(nd[i - 1][j], nd[i][j - 1]);
                    long long prev = dp[i - 1][j - 1];
                    if (prev > NEG / 2) best = max(best, prev + (long long)nums1[i - 1] * nums2[j - 1]);
                    nd[i][j] = best;
                }
            dp = move(nd);
        }
        return dp[n][m];
    }
};

