class Solution {
    public long maxScore(int[] nums1, int[] nums2, int k) {
        int n = nums1.length, m = nums2.length;
        final long NEG = Long.MIN_VALUE / 2;
        long[][] dp = new long[n + 1][m + 1];
        for (int t = 1; t <= k; t++) {
            long[][] nd = new long[n + 1][m + 1];
            for (long[] row : nd) java.util.Arrays.fill(row, NEG);
            for (int i = 1; i <= n; i++)
                for (int j = 1; j <= m; j++) {
                    long best = Math.max(nd[i - 1][j], nd[i][j - 1]);
                    long prev = dp[i - 1][j - 1];
                    if (prev > NEG / 2) best = Math.max(best, prev + (long) nums1[i - 1] * nums2[j - 1]);
                    nd[i][j] = best;
                }
            dp = nd;
        }
        return dp[n][m];
    }
}

