from functools import lru_cache
class Solution:
    def maxScore(self, nums1, nums2, k):
        n, m = len(nums1), len(nums2)
        @lru_cache(maxsize=None)
        def f(t, i, j):
            if t == 0:
                return 0
            if t > min(i, j):
                return float('-inf')
            return max(f(t, i - 1, j), f(t, i, j - 1),
                       f(t - 1, i - 1, j - 1) + nums1[i - 1] * nums2[j - 1])
        return f(k, n, m)

