class Solution {
    vector<vector<vector<long long>>> memo;
    vector<int> a, b;
    long long f(int t, int i, int j) {
        if (t == 0) return 0;
        if (t > min(i, j)) return LLONG_MIN / 2;
        long long& r = memo[t][i][j];
        if (r != LLONG_MAX) return r;
        r = max(f(t, i - 1, j), f(t, i, j - 1));
        long long take = f(t - 1, i - 1, j - 1);
        if (take > LLONG_MIN / 4) r = max(r, take + (long long)a[i - 1] * b[j - 1]);
        return r;
    }
public:
    long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {
        a = nums1; b = nums2;
        memo.assign(k + 1, vector<vector<long long>>(a.size() + 1,
               vector<long long>(b.size() + 1, LLONG_MAX)));
        return f(k, a.size(), b.size());
    }
};

