class Solution {
    Long[][][] memo;
    int[] a, b;
    long f(int t, int i, int j) {
        if (t == 0) return 0;
        if (t > Math.min(i, j)) return Long.MIN_VALUE / 2;
        if (memo[t][i][j] != null) return memo[t][i][j];
        long r = Math.max(f(t, i - 1, j), f(t, i, j - 1));
        long take = f(t - 1, i - 1, j - 1);
        if (take > Long.MIN_VALUE / 4) r = Math.max(r, take + (long) a[i - 1] * b[j - 1]);
        return memo[t][i][j] = r;
    }
    public long maxScore(int[] nums1, int[] nums2, int k) {
        a = nums1; b = nums2;
        memo = new Long[k + 1][a.length + 1][b.length + 1];
        return f(k, a.length, b.length);
    }
}

