var maxScore = function(nums1, nums2, k) {
    const memo = new Map();
    const key = (t, i, j) => t + ',' + i + ',' + j;
    function f(t, i, j) {
        if (t === 0) return 0;
        if (t > Math.min(i, j)) return -Infinity;
        const kk = key(t, i, j);
        if (memo.has(kk)) return memo.get(kk);
        const r = Math.max(f(t, i - 1, j), f(t, i, j - 1),
                           f(t - 1, i - 1, j - 1) + nums1[i - 1] * nums2[j - 1]);
        memo.set(kk, r);
        return r;
    }
    return f(k, nums1.length, nums2.length);
};
